/* *	External function definitions for string handling functions * */#define	strchr(ptr,ch)	index(ptr,ch)#define	strrchr(ptr,ch)	rindex(ptr,ch)#ifndef __GNUC__extern char	*strcat(), *strncat(),	*strcpy(), *strncpy(),	*strset(), *strnset(),	*strupr(), *strlwr(),	*index(),  *rindex(),	*strtok(), *strpbrk(),	*strstr(), *strset(),	*strnset(),  *strupr(),	*strlwr();	extern int	strcmp(), strncmp(),	strlen(), strcspn(),	strspn();#elseextern char	*strcat( char *, const char * ),	*strncat( char *, const char *, int ),	*strcpy( char *, const char * ),	*strncpy( char *, const char *, int ),	*index( const char *, char ),	*rindex( const char *, char ),	*strtok( char *, const char * ),	*strpbrk( char *, const char * ),	*strstr( const char *, const char * ),	*strdup( char * ),	*strset( char *, char ),	*strnset( char *, char, int ),	*strupr(char *),	*strlwr(char *);extern int	strcmp(const char* , const char*),	strncmp(const char* , const char*, int),  	strlen(const char *),	strspn(const char *, const char *),	strcspn(const char *, const char *);#endif